```json
{
  "root_causes": [
    {
      "service": "shipping",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.span_name, round(c.duration/1e6,1) AS client_ms, round(s.duration/1e6,1) AS quote_server_ms, round(date_diff('microsecond', c.time, s.time)/1e3,1) AS start_gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='shipping' AND c.span_name='POST quote' ORDER BY c.time LIMIT 10", "claim": "Shipping's outgoing POST quote takes ~676ms, with ~675ms before quote's server span starts; quote itself handles it in ~0.3ms."},
        {"kind": "trace", "sql": "SELECT 'ab' p, service_name, span_name, attr_span_kind, round(approx_quantile(duration,0.95)/1e6,1) p95_ms, COUNT(*) n FROM abnormal_traces WHERE service_name='shipping' AND span_name IN ('/get-quote','/ship-order','POST quote') GROUP BY 1,2,3,4 UNION ALL SELECT 'no', service_name, span_name, attr_span_kind, round(approx_quantile(duration,0.95)/1e6,1), COUNT(*) FROM normal_traces WHERE service_name='shipping' AND span_name IN ('/get-quote','/ship-order','POST quote') GROUP BY 1,2,3,4", "claim": "Shipping /get-quote and POST quote p95 rise from ~2ms to ~676ms; /ship-order stays at 0ms."},
        {"kind": "metric", "sql": "SELECT 'ab' p, service_name, metric, attr_k8s_pod_name pod, round(avg(value),1) avgv, round(max(value),1) mx FROM abnormal_metrics_sum WHERE service_name IN ('shipping','quote') AND metric IN ('k8s.pod.network.io','k8s.pod.network.errors') GROUP BY 1,2,3,4 UNION ALL SELECT 'no', service_name, metric, attr_k8s_pod_name, round(avg(value),1), round(max(value),1) FROM normal_metrics_sum WHERE service_name IN ('shipping','quote') AND metric IN ('k8s.pod.network.io','k8s.pod.network.errors') GROUP BY 1,2,3,4", "claim": "Shipping and quote network I/O and error counters are unchanged between normal and abnormal periods, with no errors."}
      ]
    }
  ],
  "propagation": [
    {"from": "shipping", "to": "checkout", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, round(approx_quantile(duration,0.95)/1e6,1) p95_ms, COUNT(*) n FROM abnormal_traces WHERE (service_name='checkout' AND span_name IN ('oteldemo.CheckoutService/PlaceOrder','prepareOrderItemsAndShippingQuoteFromCart')) OR (service_name='shipping' AND span_name='/get-quote') GROUP BY 1,2,3", "claim": "Checkout PlaceOrder and its shipping-quote preparation rise to ~690-700ms p95, matching shipping's /get-quote latency."}]},
    {"from": "checkout", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, round(approx_quantile(duration,0.95)/1e6,1) p95_ms, COUNT(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('POST /api/checkout','grpc.oteldemo.CheckoutService/PlaceOrder') GROUP BY 1,2,3", "claim": "Frontend's POST /api/checkout and its PlaceOrder client call rise to ~700ms p95, from ~33ms in normal."}]},
    {"from": "frontend", "to": "frontend-proxy", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, round(approx_quantile(duration,0.95)/1e6,1) p95_ms, COUNT(*) n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' GROUP BY 1,2", "claim": "Frontend-proxy ingress p95 rises to ~119ms in the abnormal period, from ~21ms in normal, as user POSTs wait on checkout."}]}
  ]
}
```

